export function createOfflineQueue({
  storage,
  send,
  key = "queue:v1",
  maxAttempts = 5,
}) {
  let items = [];

  try {
    const stored = JSON.parse(storage.getItem(key));
    if (Array.isArray(stored)) {
      items = stored;
    }
  } catch {
    // Invalid stored data starts an empty queue.
  }

  let inFlight = null;
  let runningFlush = null;

  function persist() {
    storage.setItem(key, JSON.stringify(items));
  }

  function enqueue(action) {
    if (items.some((item) => item.id === action.id)) {
      return;
    }

    const existing =
      action.dedupeKey !== undefined
        ? items.find(
            (item) =>
              item !== inFlight && item.dedupeKey === action.dedupeKey,
          )
        : undefined;

    if (existing) {
      existing.type = action.type;
      existing.payload = action.payload;
      existing.attempts = 0;
    } else {
      items.push({
        id: action.id,
        type: action.type,
        payload: action.payload,
        dedupeKey: action.dedupeKey,
        attempts: 0,
      });
    }

    persist();
  }

  function flush() {
    if (runningFlush !== null) {
      return runningFlush;
    }

    let resolveFlush;
    let rejectFlush;
    const promise = new Promise((resolve, reject) => {
      resolveFlush = resolve;
      rejectFlush = reject;
    });

    // Install the promise before send can make a reentrant flush call.
    runningFlush = promise;

    (async () => {
      const sent = [];
      const failed = [];

      try {
        while (items.length > 0) {
          const item = items[0];
          inFlight = item;

          let outcome = "retryable";

          try {
            const response = await send({
              id: item.id,
              type: item.type,
              payload: item.payload,
            });

            const ok = response == null ? undefined : response.ok;

            if (ok === true) {
              outcome = "success";
            } else if (ok === false && response.retryable === false) {
              outcome = "rejected";
            }
          } catch {
            // Rejections and synchronous send errors are retryable.
          }

          if (outcome === "success") {
            items.shift();
            persist();
            sent.push(item.id);
          } else if (outcome === "rejected") {
            items.shift();
            persist();
            failed.push({ id: item.id, reason: "rejected" });
          } else {
            item.attempts += 1;
            persist();

            if (item.attempts >= maxAttempts) {
              items.shift();
              persist();
              failed.push({ id: item.id, reason: "max-attempts" });
            }

            break;
          }

          inFlight = null;
        }

        resolveFlush({ sent, failed, remaining: items.length });
      } catch (error) {
        rejectFlush(error);
      } finally {
        inFlight = null;
        runningFlush = null;
      }
    })();

    return promise;
  }

  return {
    enqueue,
    flush,
    size() {
      return items.length;
    },
    peek() {
      return items.map((item) => ({
        id: item.id,
        type: item.type,
        payload: item.payload,
        dedupeKey: item.dedupeKey,
        attempts: item.attempts,
      }));
    },
  };
}
